#!/usr/bin/env bash
set -uo pipefail
export RUSTFLAGS="--cfg madsim"
fail=0
run() { echo "::group::$*"; eval "$@" 2>&1 | grep -av "^ *[0-9]*: \|^ *at " | tail -n 150; s=${PIPESTATUS[0]}; echo "::endgroup::"; echo "STATUS $s :: $*"; [ "$s" -eq 0 ] || fail=1; }
run cargo\ run\ -p\ ursula-sim\ --bin\ ursula-sim\ --\ smoke\ --failure-dir\ target/ursula-sim-failures\ --write-artifacts\ --seed-range\ 60..=199\ --seed-range\ 503..=504\ --seed-family\ http-protocol-surface-randomized\ --seed-family\ runtime-raft-network-randomized-extended\ --seed-family\ runtime-raft-network-cold-live-write-recovery\ --seed-family\ runtime-interleaving\ --seed-family\ leader-read-linearizability\ --seed-family\ leader-read-linearizability-extended\ --seed-family\ producer-repeats-exactly-once\ --seed-family\ producer-repeats-exactly-once-extended\ --seed-family\ idle-expiry-cannot-reopen-an-epoch\ --seed-family\ history-rewind-under-leader-churn\ --seed-family\ history-rewind-under-leader-churn-extended\ --seed-family\ stale-writers-after-restore\ --seed-family\ recovery-plan-cut-under-restarts\ --seed-family\ recovery-plan-cut-under-restarts-extended\ --seed-family\ recovery-plan-survivor-campaigns\ --seed-family\ recovery-plan-survivor-campaigns-extended\ --seed-family\ routing-before-body-under-leader-churn\ --seed-family\ routing-before-body-under-leader-churn-extended\ --seed-family\ marked-chunks-never-contradict\ --seed-family\ marked-chunks-never-contradict-extended\ --seed-family\ recovery-plan-membership-rollback\ --seed-family\ recovery-plan-membership-rollback-extended\ --seed-family\ deleted-data-leaves-within-bound\ --seed-family\ deleted-data-leaves-within-bound-extended\ --seed-family\ deleted-data-across-segments\ --seed-family\ deleted-data-across-segments-extended\ --seed-family\ deleted-data-after-expiry\ --seed-family\ deleted-data-after-expiry-extended\ --seed-family\ engine-restart-leaves-no-work\ --seed-family\ engine-restart-leaves-no-work-extended\ --seed-family\ snapshot-objects-stay-owned\ --seed-family\ snapshot-objects-stay-owned-extended\ --seed-family\ placement-move
echo "OVERALL $fail"; exit $fail
